    0xF0,0x90,0xF0,0x90,0xF0, // 8
    0xF0,0x90,0xF0,0x10,0xF0, // 9
    0xF0,0x90,0xF0,0x90,0x90, // A
    0xE0,0x90,0xE0,0x90,0xE0, // B
    0xF0,0x80,0x80,0x80,0xF0, // C
    0xE0,0x90,0x90,0x90,0xE0, // D
    0xF0,0x80,0xF0,0x80,0xF0, // E
    0xF0,0x80,0xF0,0x80,0x80  // F
  ];

  // Demo ROM: Draw a sprite and move it with keys
  // This program draws a 8x5 sprite at V0,V1 and moves it with keys 1 and 4
  // The sprite is a smiley face
  const demoROM = [
    0x60, 0x1A,       // LD V0, 0x1A       ; X pos
    0x61, 0x0A,       // LD V1, 0x0A       ; Y pos
    0xA2, 0x10,       // LD I, 0x210       ; Sprite data
    // Draw sprite loop start
    0xD0, 0x15,       // DRW V0, V1, 5
    // Wait for key press
    0xF0, 0x0A,       // LD V0, K
    0x30, 0x01,       // SE V0, 0x01
    0x12, 0x00,       // JP 0x200
    0x30, 0x04,       // SE V0, 0x04
    0x70, 0x01,       // ADD V0, 0x01
    0x12, 0x00,       // JP 0x200
    0x30, 0x00,       // SE V0, 0x00
    0x12, 0x00,       // JP 0x200
    0x12, 0x06,       // JP 0x206
    // Sprite data at 0x210
