    0x42,             // 01000010
    0xA9,             // 10101001
    0x85,             // 10000101
    0x3C              // 00111100
  ];

  // Utility: format number as hex with leading zeros
  function toHex(value, length) {
    return value.toString(16).toUpperCase().padStart(length, '0');
  }

  class Chip8 {
    constructor() {
      this.memory = new Uint8Array(MEMORY_SIZE);
      this.V = new Uint8Array(16);  // V0 to VF
      this.I = 0;                  // Index register
      this.pc = PROGRAM_START;     // Program counter
      this.stack = [];
      this.delayTimer = 0;
      this.soundTimer = 0;
      this.display = new Uint8Array(DISPLAY_WIDTH * DISPLAY_HEIGHT);
      this.keys = new Array(16).fill(false);
      this.drawFlag = false;
      this.waitForKey = false;
      this.waitRegister = 0;

      // Load fontset
      for (let i = 0; i < FONTSET.length; i++) {
        this.memory[FONT_START + i] = FONTSET[i];
      }
    }

    reset() {
      this.memory.fill(0);
      this.V.fill(0);
      this.I = 0;
      this.pc = PROGRAM_START;
      this.stack = [];
      this.delayTimer = 0;
      this.soundTimer = 0;
      this.display.fill(0);
      this.keys.fill(false);
      this.drawFlag = false;
      this.waitForKey = false;
      this.waitRegister = 0;
      // Reload fontset
      for (let i = 0; i < FONTSET.length; i++) {
        this.memory[FONT_START + i] = FONTSET[i];
      }
    }

    loadProgram(program) {
      this.reset();
      this.memory.set(program, PROGRAM_START);
      this.pc = PROGRAM_START;
    }

    setKeyDown(keyIndex) {
      this.keys[keyIndex] = true;
      if (this.waitForKey) {
        this.V[this.waitRegister] = keyIndex;
        this.waitForKey = false;
      }
    }
    setKeyUp(keyIndex) {
      this.keys[keyIndex] = false;
    }

    cycle() {
      if (this.waitForKey) return; // Pause cycle if waiting for key

      // Fetch opcode
      let opcode = (this.memory[this.pc] << 8) | this.memory[this.pc + 1];
      this.executeOpcode(opcode);
    }

    executeOpcode(opcode) {
      this.drawFlag = false;
      const x = (opcode & 0x0F00) >> 8;
      const y = (opcode & 0x00F0) >> 4;
      const n = opcode & 0x000F;
      const nn = opcode & 0x00FF;
      const nnn = opcode & 0x0FFF;

      // Save pc before increment for debugger
      const oldPC = this.pc;

      switch(opcode & 0xF000) {
        case 0x0000:
          switch (opcode) {
            case 0x00E0: // CLS
              this.display.fill(0);
              this.drawFlag = true;
              this.pc += 2;
              break;
            case 0x00EE: // RET
              if (this.stack.length === 0) throw new Error("Stack underflow on RET");
              this.pc = this.stack.pop();
              this.pc += 2;
              break;
            default:
              // 0NNN call RCA 1802 program, ignored
              this.pc += 2;
              break;
          }
          break;
        case 0x1000: // JP addr
          this.pc = nnn;
          break;
        case 0x2000: // CALL addr
          this.stack.push(this.pc);
          this.pc = nnn;
          break;
        case 0x3000: // SE Vx, byte
          if (this.V[x] === nn) {
            this.pc += 4;
          } else {
            this.pc += 2;
          }
          break;
        case 0x4000: // SNE Vx, byte
          if (this.V[x] !== nn) {
            this.pc += 4;
          } else {
            this.pc += 2;
          }
          break;
        case 0x5000: // SE Vx, Vy
          if (this.V[x] === this.V[y]) {
            this.pc += 4;
          } else {
            this.pc += 2;
          }
          break;
        case 0x6000: // LD Vx, byte
          this.V[x] = nn;
          this.pc += 2;
          break;
        case 0x7000: // ADD Vx, byte
          this.V[x] = (this.V[x] + nn) & 0xFF;
          this.pc += 2;
          break;
        case 0x8000:
          switch (n) {
            case 0x0: // LD Vx, Vy
              this.V[x] = this.V[y];
              break;
            case 0x1: // OR Vx, Vy
              this.V[x] |= this.V[y];
              break;
            case 0x2: // AND Vx, Vy
              this.V[x] &= this.V[y];
              break;
            case 0x3: // XOR Vx, Vy
              this.V[x] ^= this.V[y];
              break;
            case 0x4: // ADD Vx, Vy
              {
                let sum = this.V[x] + this.V[y];
                this.V[0xF] = sum > 0xFF ? 1 : 0;
                this.V[x] = sum & 0xFF;
              }
              break;
            case 0x5: // SUB Vx, Vy
              {
                this.V[0xF] = this.V[x] >= this.V[y] ? 1 : 0;
                this.V[x] = (this.V[x] - this.V[y]) & 0xFF;
              }
              break;
            case 0x6: // SHR Vx {, Vy}
              {
                this.V[0xF] = this.V[x] & 0x1;
                this.V[x] >>= 1;
              }
              break;
            case 0x7: // SUBN Vx, Vy
              {
                this.V[0xF] = this.V[y] >= this.V[x] ? 1 : 0;
                this.V[x] = (this.V[y] - this.V[x]) & 0xFF;
              }
              break;
            case 0xE: // SHL Vx {, Vy}
              {
                this.V[0xF] = (this.V[x] & 0x80) >> 7;
                this.V[x] = (this.V[x] << 1) & 0xFF;
              }
              break;
            default:
              throw new Error("Unknown opcode [0x8000]: " + opcode.toString(16));
          }
          this.pc += 2;
          break;
        case 0x9000: // SNE Vx, Vy
          if (this.V[x] !== this.V[y]) {
            this.pc += 4;
          } else {
            this.pc += 2;
          }
          break;
        case 0xA000: // LD I, addr
          this.I = nnn;
          this.pc += 2;
          break;
        case 0xB000: // JP V0, addr
          this.pc = nnn + this.V[0];
          break;
        case 0xC000: // RND Vx, byte
          this.V[x] = (Math.floor(Math.random() * 0x100) & nn);
          this.pc += 2;
          break;
        case 0xD000: // DRW Vx, Vy, nibble
          {
            const width = 8;
            const height = n;
            this.V[0xF] = 0;
            for (let row = 0; row < height; row++) {
              const spriteByte = this.memory[this.I + row];
              for (let col = 0; col < width; col++) {
                const spritePixel = (spriteByte >> (7 - col)) & 1;
                const xCoord = (this.V[x] + col) % DISPLAY_WIDTH;
                const yCoord = (this.V[y] + row) % DISPLAY_HEIGHT;
                const index = xCoord + yCoord * DISPLAY_WIDTH;
                if (spritePixel === 1) {
                  if (this.display[index] === 1) {
                    this.V[0xF] = 1;
                  }
                  this.display[index] ^= 1;
                }
              }
            }
            this.drawFlag = true;
            this.pc += 2;
          }
          break;
        case 0xE000:
          switch (nn) {
            case 0x9E: // SKP Vx
              if (this.keys[this.V[x]]) {
                this.pc += 4;
              } else {
                this.pc += 2;
              }
              break;
            case 0xA1: // SKNP Vx
              if (!this.keys[this.V[x]]) {
                this.pc += 4;
              } else {
                this.pc += 2;
              }
              break;
            default:
              throw new Error("Unknown opcode [0xE000]: " + opcode.toString(16));
          }
          break;
        case 0xF000:
          switch (nn) {
            case 0x07: // LD Vx, DT
              this.V[x] = this.delayTimer;
              this.pc += 2;
              break;
            case 0x0A: // LD Vx, K
              this.waitForKey = true;
              this.waitRegister = x;
              this.pc += 2; // Typically PC is not incremented until key pressed, but here we increment to avoid freeze
              break;
            case 0x15: // LD DT, Vx
              this.delayTimer = this.V[x];
              this.pc += 2;
              break;
            case 0x18: // LD ST, Vx
              this.soundTimer = this.V[x];
              this.pc += 2;
              break;
            case 0x1E: // ADD I, Vx
              this.I = (this.I + this.V[x]) & 0xFFFF;
              this.pc += 2;
              break;
            case 0x29: // LD F, Vx
              this.I = FONT_START + this.V[x] * 5;
              this.pc += 2;
              break;
            case 0x33: // LD B, Vx
              {
                let val = this.V[x];
                this.memory[this.I] = Math.floor(val / 100);
                this.memory[this.I + 1] = Math.floor((val % 100) / 10);
                this.memory[this.I + 2] = val % 10;
                this.pc += 2;
              }
              break;
            case 0x55: // LD [I], V0..Vx
              for (let i = 0; i <= x; i++) {
                this.memory[this.I + i] = this.V[i];
              }
              this.pc += 2;
              break;
            case 0x65: // LD V0..Vx, [I]
              for (let i = 0; i <= x; i++) {
                this.V[i] = this.memory[this.I + i];
              }
              this.pc += 2;
              break;
            default:
              throw new Error("Unknown opcode [0xF000]: " + opcode.toString(16));
          }
          break;
        default:
          throw new Error("Unknown opcode: " + opcode.toString(16));
      }

      this.decodedInstruction = Chip8.decodeInstruction(opcode);
    }

    static decodeInstruction(opcode) {
      const x = (opcode & 0x0F00) >> 8;
      const y = (opcode & 0x00F0) >> 4;
      const n = opcode & 0x000F;
      const nn = opcode & 0x00FF;
      const nnn = opcode & 0x0FFF;

      switch (opcode & 0xF000) {
        case 0x0000:
          switch (opcode) {
            case 0x00E0: return "CLS";
            case 0x00EE: return "RET";
            default: return `SYS ${toHex(nnn,3)}`;
          }
        case 0x1000: return `JP ${toHex(nnn,3)}`;
        case 0x2000: return `CALL ${toHex(nnn,3)}`;
        case 0x3000: return `SE V${x.toString(16).toUpperCase()}, ${toHex(nn,2)}`;
        case 0x4000: return `SNE V${x.toString(16).toUpperCase()}, ${toHex(nn,2)}`;
        case 0x5000: return `SE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
        case 0x6000: return `LD V${x.toString(16).toUpperCase()}, ${toHex(nn,2)}`;
        case 0x7000: return `ADD V${x.toString(16).toUpperCase()}, ${toHex(nn,2)}`;
        case 0x8000:
          switch(n) {
            case 0x0: return `LD V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            case 0x1: return `OR V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            case 0x2: return `AND V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            case 0x3: return `XOR V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            case 0x4: return `ADD V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            case 0x5: return `SUB V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            case 0x6: return `SHR V${x.toString(16).toUpperCase()}`;
            case 0x7: return `SUBN V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            case 0xE: return `SHL V${x.toString(16).toUpperCase()}`;
            default: return `UNKNOWN 0x8000 ${toHex(opcode,4)}`;
          }
        case 0x9000: return `SNE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
        case 0xA000: return `LD I, ${toHex(nnn,3)}`;
        case 0xB000: return `JP V0, ${toHex(nnn,3)}`;
        case 0xC000: return `RND V${x.toString(16).toUpperCase()}, ${toHex(nn,2)}`;
        case 0xD000: return `DRW V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}, ${n}`;
        case 0xE000:
          switch(nn) {
            case 0x9E: return `SKP V${x.toString(16).toUpperCase()}`;
            case 0xA1: return `SKNP V${x.toString(16).toUpperCase()}`;
            default: return `UNKNOWN 0xE000 ${toHex(opcode,4)}`;
          }
        case 0xF000:
          switch (nn) {
            case 0x07: return `LD V${x.toString(16).toUpperCase()}, DT`;
            case 0x0A: return `LD V${x.toString(16).toUpperCase()}, K`;
            case 0x15: return `LD DT, V${x.toString(16).toUpperCase()}`;
            case 0x18: return `LD ST, V${x.toString(16).toUpperCase()}`;
            case 0x1E: return `ADD I, V${x.toString(16).toUpperCase()}`;
            case 0x29: return `LD F, V${x.toString(16).toUpperCase()}`;
            case 0x33: return `LD B, V${x.toString(16).toUpperCase()}`;
            case 0x55: return `LD [I], V0..V${x.toString(16).toUpperCase()}`;
            case 0x65: return `LD V0..V${x.toString(16).toUpperCase()}, [I]`;
            default: return `UNKNOWN 0xF000 ${toHex(opcode,4)}`;
          }
        default: return `UNKNOWN ${toHex(opcode,4)}`;
      }
    }
  }

  // Setup display canvas
  const canvas = document.getElementById('chip8-screen');
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, DISPLAY_WIDTH, DISPLAY_HEIGHT);

  function drawDisplay(display) {
    const imageData = ctx.createImageData(DISPLAY_WIDTH, DISPLAY_HEIGHT);
    for (let i = 0; i < display.length; i++) {
      const pixel = display[i];
      const color = pixel ? 255 : 0;
      imageData.data[i * 4 + 0] = color;
      imageData.data[i * 4 + 1] = color;
      imageData.data[i * 4 + 2] = color;
      imageData.data[i * 4 + 3] = 255;
    }
    ctx.putImageData(imageData, 0, 0);
  }

  // Setup keypad UI and keyboard mapping
  const keypadDiv = document.getElementById('keypad');
  const keyElements = [];
  const keyMap = {};
  // Map physical keyboard keys to CHIP-8 keys
  const physicalToChip8 = {
    '1': 0x1, '2': 0x2, '3': 0x3, '4': 0xC,
    'q': 0x4, 'w': 0x5, 'e': 0x6, 'r': 0xD,
    'a': 0x7, 's': 0x8, 'd': 0x9, 'f': 0xE,
    'z': 0xA, 'x': 0x0, 'c': 0xB, 'v': 0xF
  };

  for (let i = 0; i < KEYPAD_KEYS.length; i++) {
    const keyChar = KEYPAD_KEYS[i];
    const div = document.createElement('div');
    div.className = 'key';
    div.textContent = keyChar;
    keypadDiv.appendChild(div);
    keyElements.push(div);
  }

  // Initialize Chip8 instance
  const chip8 = new Chip8();
  chip8.loadProgram(new Uint8Array(demoROM));

  // Update debug panel
  function updateDebugger() {
    const registersTable = document.getElementById('registers-table');
    registersTable.innerHTML = '';
    for (let i = 0; i < 16; i++) {
      const tr = document.createElement('tr');
      const tdName = document.createElement('td');
      tdName.textContent = `V${i.toString(16).toUpperCase()}`;
      const tdValue = document.createElement('td');
      tdValue.textContent = toHex(chip8.V[i], 2);
      tr.appendChild(tdName);
      tr.appendChild(tdValue);
      registersTable.appendChild(tr);
    }

    document.getElementById('reg-i').textContent = toHex(chip8.I, 4);
    document.getElementById('reg-pc').textContent = toHex(chip8.pc, 3);
    document.getElementById('reg-dt').textContent = toHex(chip8.delayTimer, 2);
    document.getElementById('reg-st').textContent = toHex(chip8.soundTimer, 2);

    const stackList = document.getElementById('stack-list');
    stackList.innerHTML = '';
    for (let i = chip8.stack.length - 1; i >= 0; i--) {
      const tr = document.createElement('tr');
      const td = document.createElement('td');
      td.textContent = toHex(chip8.stack[i], 3);
      tr.appendChild(td);
      stackList.appendChild(tr);
    }

    document.getElementById('instruction-decoded').textContent = `Instruction: ${chip8.decodedInstruction || 'N/A'}`;
  }

  // Run loop and timers
  let running = false;
  let instructionSpeed = 10; // instructions per frame

  function mainLoop() {
    if (running) {
      try {
        for (let i = 0; i < instructionSpeed; i++) {
          chip8.cycle();
        }
      } catch (e) {
        alert('Error executing opcode: ' + e.message);
        running = false;
        updateButtons();
      }

      if (chip8.drawFlag) {
        drawDisplay(chip8.display);
        chip8.drawFlag = false;
      }

      updateDebugger();
    }
    requestAnimationFrame(mainLoop);
  }

  // Timers decrement at 60Hz
  setInterval(() => {
    if (chip8.delayTimer > 0) chip8.delayTimer--;
    if (chip8.soundTimer > 0) chip8.soundTimer--;
  }, 1000 / TIMER_FREQUENCY);

  // Keyboard event handlers
  window.addEventListener('keydown', (e) => {
    const key = e.key.toLowerCase();
    if (key in physicalToChip8) {
      const chip8Key = physicalToChip8[key];
      chip8.setKeyDown(chip8Key);
      keyElements[chip8Key].classList.add('pressed');
      e.preventDefault();
    }
  });
  window.addEventListener('keyup', (e) => {
    const key = e.key.toLowerCase();
    if (key in physicalToChip8) {
      const chip8Key = physicalToChip8[key];
      chip8.setKeyUp(chip8Key);
      keyElements[chip8Key].classList.remove('pressed');
      e.preventDefault();
    }
  });

  // Control buttons
  const runBtn = document.getElementById('run-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const stepBtn = document.getElementById('step-btn');
  const resetBtn = document.getElementById('reset-btn');
  const speedRange = document.getElementById('speed-range');
  const speedDisplay = document.getElementById('speed-display');

  runBtn.addEventListener('click', () => {
    running = true;
    updateButtons();
  });
  pauseBtn.addEventListener('click', () => {
    running = false;
    updateButtons();
  });
  stepBtn.addEventListener('click', () => {
    try {
      chip8.cycle();
      if (chip8.drawFlag) {
        drawDisplay(chip8.display);
        chip8.drawFlag = false;
      }
      updateDebugger();
    } catch (e) {
      alert('Error executing opcode: ' + e.message);
      running = false;
      updateButtons();
    }
  });
  resetBtn.addEventListener('click', () => {
    chip8.reset();
    chip8.loadProgram(new Uint8Array(demoROM));
    drawDisplay(chip8.display);
    updateDebugger();
    running = false;
    updateButtons();
  });
  speedRange.addEventListener('input', () => {
    instructionSpeed = parseInt(speedRange.value, 10);
    speedDisplay.textContent = instructionSpeed.toString();
  });

  function updateButtons() {
    runBtn.disabled = running;
    pauseBtn.disabled = !running;
  }

  // Load ROM from file
  const romFileInput = document.getElementById('rom-file');
  romFileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const arrayBuffer = event.target.result;
      const romData = new Uint8Array(arrayBuffer);
      try {
        chip8.loadProgram(romData);
        drawDisplay(chip8.display);
        updateDebugger();
        running = false;
        updateButtons();
      } catch(e) {
        alert('Failed to load ROM: ' + e.message);
      }
    };
    reader.readAsArrayBuffer(file);
  });

  // Initialize UI
  drawDisplay(chip8.display);
  updateDebugger();
  updateButtons();
  mainLoop();
})();
</script>
</body>
</html>
